const sites=$('تهيئة المواقع').all().map(i=>i.json);
const gscDaily=$('GSC — أداء 28 يوم').all().map(i=>i.json);
const gscTop=$('GSC — الصفحات والاستعلامات').all().map(i=>i.json);
const gscSitemaps=$('GSC — Sitemaps').all().map(i=>i.json);
const inspectionMeta=$('جهز URL Inspection').all().map(i=>i.json);
const inspectionOut=$('GSC — URL Inspection').all().map(i=>i.json);
const homeOut=$('Live — الصفحة الرئيسية').all().map(i=>i.json);
const robotsOut=$('Live — robots.txt').all().map(i=>i.json);
const sitemapOut=$('Live — sitemap.xml').all().map(i=>i.json);
const psiMeta=$('جهز PageSpeed Mobile').all().map(i=>i.json);
const psiOut=$('PageSpeed — Mobile').all().map(i=>i.json);

const bodyOf=x=>{
  if(typeof x==='string') return x;
  if(typeof x?.body==='string') return x.body;
  if(typeof x?.data==='string') return x.data;
  return '';
};
const statusOf=x=>Number(x?.statusCode||x?.status||0)||null;
const decode=s=>String(s||'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>');
const attr=(tag,name)=>{
