const robotsAudit=txt=>{
  txt=String(txt||'');
  return {
    bytes:txt.length,
    sitemapDirectives:[...txt.matchAll(/^\s*Sitemap:\s*(.+)$/gmi)].map(m=>m[1].trim()),
    disallow:[...txt.matchAll(/^\s*Disallow:\s*(.*)$/gmi)].map(m=>m[1].trim()).filter(Boolean).slice(0,100),
    blocksAll:/User-agent:\s*\*[\s\S]{0,300}Disallow:\s*\/\s*$/mi.test(txt)
  };
};

const sitemapAudit=xml=>{
  xml=String(xml||'');
  const locs=[...xml.matchAll(/<loc>\s*([\s\S]*?)\s*<\/loc>/gi)].map(m=>decode(m[1].trim()));
  const isIndex=/<sitemapindex\b/i.test(xml);
  return {
    bytes:xml.length,
    type:isIndex?'sitemapindex':(/<urlset\b/i.test(xml)?'urlset':'unknown'),
    locCount:locs.length,
    pageUrlCount:isIndex?0:locs.length,
    sitemapFileCount:isIndex?locs.length:0,
    locs:locs.slice(0,500)
  };
};

const inspectionBySite={};
inspectionOut.forEach((o,i)=>{
  const meta=inspectionMeta[i]||{};
  const r=o.inspectionResult?.indexStatusResult||{};
  (inspectionBySite[meta.siteUrl]||=[]).push({
    url:meta.inspectionUrl,
    verdict:r.verdict,
    coverageState:r.coverageState,
    robotsTxtState:r.robotsTxtState,
    indexingState:r.indexingState,
    pageFetchState:r.pageFetchState,
    lastCrawlTime:r.lastCrawlTime,
    googleCanonical:r.googleCanonical,
    userCanonical:r.userCanonical,
    referringUrls:r.referringUrls||[],
    sitemap:r.sitemap||[]
  });
});

const psiBySite={};
psiOut.forEach((o,i)=>{
  const meta=psiMeta[i]||{};
  const cats=o.lighthouseResult?.categories||{};
  const audits=o.lighthouseResult?.audits||{};
  const score=k=>cats[k]?.score==null?null:Math.round(cats[k].score*100);
  const metric=k=>({value:audits[k]?.numericValue??null,display:audits[k]?.displayValue??null,score:audits[k]?.score??null});
  psiBySite[meta.siteName]={
    ok:!!o.lighthouseResult,
    errorCode:o?.error?.code||null,
    error:o?.error?.message||o?.message||null,
    quotaExceeded:Number(o?.error?.code||0)===429,
    performance:score('performance'),
    seo:score('seo'),
    accessibility:score('accessibility'),
    metrics:{
      fcp:metric('first-contentful-paint'),
      lcp:metric('largest-contentful-paint'),
      cls:metric('cumulative-layout-shift'),
      tbt:metric('total-blocking-time'),
      speedIndex:metric('speed-index')
    }
  };
});

const reports=sites.map((s,i)=>{
  const daily=gscDaily[i]?.rows||[];
  const clicks=daily.reduce((a,r)=>a+Number(r.clicks||0),0);
  const impressions=daily.reduce((a,r)=>a+Number(r.impressions||0),0);
  const ctr=impressions?clicks/impressions:0;
  const position=impressions?daily.reduce((a,r)=>a+Number(r.position||0)*Number(r.impressions||0),0)/impressions:0;

  const maps=gscSitemaps[i]?.sitemap||[];
  let submitted=0,indexed=0;
  maps.forEach(x=>(x.contents||[]).forEach(c=>{
    submitted+=Number(c.submitted||0);
    indexed+=Number(c.indexed||0);
  }));

  const home=bodyOf(homeOut[i]);
  const robots=bodyOf(robotsOut[i]);
  const sitemap=bodyOf(sitemapOut[i]);

  return {
    name:s.name,
    url:s.publicUrl,
    period:{start:s.startDate,end:s.endDate},
    gsc:{
      clicks,
      impressions,
      ctrPercent:Number((ctr*100).toFixed(2)),
      avgPosition:Number(position.toFixed(2)),
      top:(gscTop[i]?.rows||[]).slice(0,100)
    },
    sitemapInventory:{
      gscSitemaps:maps.length,
      submitted,
      indexed,
      live:sitemapAudit(sitemap)
    },
    inspection:inspectionBySite[s.siteUrl]||[],
    live:{
      homeStatus:statusOf(homeOut[i]),
      robotsStatus:statusOf(robotsOut[i]),
      sitemapStatus:statusOf(sitemapOut[i]),
      home:htmlAudit(home,hostnameOf(s.publicUrl)),
      robots:robotsAudit(robots)
    },
    pagespeed:psiBySite[s.name]||{ok:false,error:'No PageSpeed result'}
  };
});

const issueCounts={P0:0,P1:0,P2:0,P3:0};
const issues=[];
for(const s of reports){
  if(s.live.robots.blocksAll){issueCounts.P0++;issues.push({site:s.name,severity:'P0',issue:'robots.txt blocks all crawlers'});}
  if(s.live.homeStatus && s.live.homeStatus>=400){issueCounts.P0++;issues.push({site:s.name,severity:'P0',issue:'Homepage HTTP '+s.live.homeStatus});}
  if(!s.live.home.canonical){issueCounts.P1++;issues.push({site:s.name,severity:'P1',issue:'Missing canonical on homepage'});}
  if(s.live.home.h1Count===0){issueCounts.P1++;issues.push({site:s.name,severity:'P1',issue:'Missing H1 on homepage'});}
  if(s.live.home.imagesMissingAlt>0){issueCounts.P2++;issues.push({site:s.name,severity:'P2',issue:'Images missing alt: '+s.live.home.imagesMissingAlt});}
  const mismatches=s.inspection.filter(x=>x.googleCanonical&&x.userCanonical&&x.googleCanonical!==x.userCanonical).length;
  if(mismatches){issueCounts.P1++;issues.push({site:s.name,severity:'P1',issue:'Canonical mismatch on '+mismatches+' inspected URLs'});}
  if(s.pagespeed.quotaExceeded){issueCounts.P3++;issues.push({site:s.name,severity:'P3',issue:'PageSpeed API quota exhausted — retry after quota reset or raise quota'});}
}

return [{
  json:{
    generatedAt:new Date().toISOString(),
    methodology:'NotebookLM MASTER SEO + AEO + GEO 2026',
    reports,
    issues,
    issueCounts,
    agentPrompt:`حلل هذا التقرير كـ Weyaak Site Intelligence Supervisor. التزم بالأدلة فقط. رتب المشاكل P0/P1/P2/P3. افصل لكل موقع: inventory, indexing, crawlability, technical SEO, performance, schema, AEO, GEO/entity, visual SEO. اذكر عدد صفحات sitemap الحية وGSC submitted/indexed، حالة URL Inspection، وأداء البحث. إذا PageSpeed quotaExceeded=true لا تخترع أرقام سرعة؛ اذكر أن القياس مؤجل. اختم بخطة تطوير مرتبة حسب التأثير والمخاطر. البيانات: ${JSON.stringify(reports)}`
  }
}];

